-- ═══════════════════════════════════════════════════════════
-- 0098_food_recettes_sauces_cremes_genoise_15_11.sql
-- STATUT : PROPOSITION — à exécuter puis confirmer par Renée-Lise
-- Auteur : Claude Code · Date de rédaction : 2026-11-15
-- Objet : 16 fiches recettes supplémentaires pour Bella'Food,
--   transcrites depuis les images envoyées ce jour (confirmé par
--   Renée-Lise : à ajouter à Bella'Food) — 12 sauces dessert
--   (infographies "Recettes de Sauces Dessert" et "Six délicieuses
--   sauces dessert"), 3 variantes de crème pâtissière (classique,
--   chocolat, sans œufs), et la génoise pour layer cake (quantités
--   pour toutes les tailles de moule détaillées en notes, recette
--   de base donnée pour un moule de 20 cm).
--   Table food_recettes uniquement, pas de prix conseillé →
--   volontairement non synchronisé vers catalogue_produits.
--   Non repris dans ce lot : la fiche "Tartelette chocolat caramel"
--   envoyée à nouveau dans ce même batch est un doublon exact de
--   l'image déjà traitée le 14/11 (migration 0097) — pas réinsérée
--   pour éviter un doublon de fiche.
--   Autres images du même envoi (fiches de grammaire CE2, écriture,
--   syllabes — confirmé par Renée-Lise : matériel Mo Ti-Péyi) et la
--   citation isolée ne concernent pas Bella'Food — non traitées ici.
-- Idempotent (WHERE NOT EXISTS sur nom + notes).
-- ═══════════════════════════════════════════════════════════

insert into public.food_recettes
  (nom, categorie, nb_parts, difficulte, temps_prepa, temps_cuisson, temps_repos, ingredients, etapes, notes, statut)
select v.nom, v.categorie, v.nb_parts, v.difficulte, v.temps_prepa, v.temps_cuisson, v.temps_repos, v.ingredients, v.etapes, v.notes, v.statut
from (values
('Sauce Caramel', 'sauce', 4, 1, 10, 10, null, '[{"nom": "Sucre", "quantite": 200, "unite": "g"}, {"nom": "Beurre", "quantite": 80, "unite": "g"}, {"nom": "Crème liquide", "quantite": 160, "unite": "ml"}, {"nom": "Sel", "quantite": 1, "unite": "pincée"}]'::jsonb, ARRAY['Faites fondre le sucre à sec dans une casserole à feu moyen jusqu''à obtenir un caramel ambré.','Hors du feu, incorporez le beurre en morceaux en remuant.','Ajoutez la crème liquide chaude petit à petit en fouettant (attention aux projections).','Ajoutez la pincée de sel, remettez sur feu doux 1 à 2 minutes pour lisser, puis laissez tiédir.']::text[], 'Fiche recette envoyée par Renée-Lise le 15/11 — repère interne (composition/préparation), pas de prix de vente associé.', 'actif'),
('Sauce Chocolat', 'sauce', 4, 1, 10, 5, null, '[{"nom": "Crème liquide", "quantite": 160, "unite": "ml"}, {"nom": "Chocolat noir", "quantite": 150, "unite": "g"}, {"nom": "Sucre", "quantite": 50, "unite": "g"}, {"nom": "Extrait de vanille", "quantite": 1, "unite": "c. à café"}]'::jsonb, ARRAY['Faites chauffer la crème liquide avec le sucre jusqu''à frémissement.','Hors du feu, versez sur le chocolat noir haché et laissez fondre 1 minute.','Mélangez jusqu''à obtenir une sauce lisse et brillante, ajoutez la vanille.']::text[], 'Fiche recette envoyée par Renée-Lise le 15/11 — repère interne (composition/préparation), pas de prix de vente associé.', 'actif'),
('Sauce Fraise', 'sauce', 4, 1, 10, 5, null, '[{"nom": "Fraises fraîches", "quantite": 300, "unite": "g"}, {"nom": "Jus de citron", "quantite": 2, "unite": "c. à soupe"}, {"nom": "Sucre", "quantite": 100, "unite": "g"}]'::jsonb, ARRAY['Mixez les fraises avec le jus de citron et le sucre.','Faites chauffer le mélange quelques minutes à feu doux jusqu''à léger épaississement.','Passez éventuellement au chinois pour retirer les pépins, laissez refroidir.']::text[], 'Fiche recette envoyée par Renée-Lise le 15/11 — repère interne (composition/préparation), pas de prix de vente associé.', 'actif'),
('Sauce Framboise', 'sauce', 4, 1, 10, 5, null, '[{"nom": "Framboises fraîches ou surgelées", "quantite": 300, "unite": "g"}, {"nom": "Sucre", "quantite": 100, "unite": "g"}, {"nom": "Extrait de vanille", "quantite": 1, "unite": "c. à café"}]'::jsonb, ARRAY['Faites chauffer les framboises avec le sucre jusqu''à ce qu''elles se défassent.','Mixez puis passez au chinois pour retirer les pépins.','Ajoutez la vanille et laissez refroidir.']::text[], 'Fiche recette envoyée par Renée-Lise le 15/11 — repère interne (composition/préparation), pas de prix de vente associé.', 'actif'),
('Sauce Vanille', 'sauce', 4, 2, 15, 10, null, '[{"nom": "Lait", "quantite": 250, "unite": "ml"}, {"nom": "Jaunes d''œufs", "quantite": 3, "unite": "piece"}, {"nom": "Sucre", "quantite": 60, "unite": "g"}, {"nom": "Extrait de vanille", "quantite": 1, "unite": "c. à café"}]'::jsonb, ARRAY['Faites chauffer le lait avec la vanille jusqu''à frémissement.','Fouettez les jaunes d''œufs avec le sucre jusqu''à blanchiment.','Versez le lait chaud sur les jaunes en fouettant, remettez sur feu doux et faites épaissir sans bouillir (type crème anglaise).','Laissez refroidir en remuant de temps en temps.']::text[], 'Fiche recette envoyée par Renée-Lise le 15/11 — repère interne (composition/préparation), pas de prix de vente associé.', 'actif'),
('Sauce Citron', 'sauce', 4, 1, 10, 8, null, '[{"nom": "Sucre", "quantite": 150, "unite": "g"}, {"nom": "Eau", "quantite": 100, "unite": "ml"}, {"nom": "Jus de citron", "quantite": 120, "unite": "ml"}, {"nom": "Beurre", "quantite": 40, "unite": "g"}]'::jsonb, ARRAY['Faites chauffer l''eau et le sucre jusqu''à dissolution complète.','Ajoutez le jus de citron et laissez réduire légèrement à feu doux.','Hors du feu, incorporez le beurre en morceaux en fouettant jusqu''à obtenir une sauce brillante.']::text[], 'Fiche recette envoyée par Renée-Lise le 15/11 — repère interne (composition/préparation), pas de prix de vente associé.', 'actif'),
('Sauce au Chocolat', 'sauce', 4, 1, 10, 8, null, '[{"nom": "Cacao en poudre", "quantite": 50, "unite": "g"}, {"nom": "Sucre", "quantite": 200, "unite": "g"}, {"nom": "Eau", "quantite": 240, "unite": "ml"}, {"nom": "Beurre", "quantite": 1, "unite": "c. à soupe"}, {"nom": "Extrait de vanille", "quantite": 1, "unite": "c. à café"}, {"nom": "Sel", "quantite": 1, "unite": "pincée"}]'::jsonb, ARRAY['Mélangez le cacao et le sucre dans une casserole, ajoutez l''eau progressivement en fouettant.','Faites chauffer à feu moyen en remuant jusqu''à léger épaississement.','Hors du feu, ajoutez le beurre, la vanille et le sel, mélangez jusqu''à obtenir une sauce lisse.']::text[], 'Fiche recette envoyée par Renée-Lise le 15/11 — repère interne (composition/préparation), pas de prix de vente associé.', 'actif'),
('Sauce au Chocolat Noir', 'sauce', 4, 1, 10, 5, null, '[{"nom": "Chocolat noir, haché", "quantite": 200, "unite": "g"}, {"nom": "Crème liquide (fleurette)", "quantite": 240, "unite": "ml"}, {"nom": "Sucre", "quantite": 2, "unite": "c. à soupe"}, {"nom": "Beurre", "quantite": 1, "unite": "c. à soupe"}]'::jsonb, ARRAY['Faites chauffer la crème liquide avec le sucre jusqu''à frémissement.','Versez sur le chocolat noir haché, laissez fondre 1 minute puis mélangez.','Incorporez le beurre et mélangez jusqu''à obtenir une sauce lisse et brillante.']::text[], 'Fiche recette envoyée par Renée-Lise le 15/11 — repère interne (composition/préparation), pas de prix de vente associé.', 'actif'),
('Sauce au Chocolat Blanc', 'sauce', 4, 1, 10, 5, null, '[{"nom": "Chocolat blanc, haché finement", "quantite": 200, "unite": "g"}, {"nom": "Crème liquide", "quantite": 180, "unite": "ml"}, {"nom": "Beurre", "quantite": 1, "unite": "c. à soupe"}, {"nom": "Extrait de vanille", "quantite": 1, "unite": "c. à café", "notes": "1/2 c. à café"}]'::jsonb, ARRAY['Faites chauffer la crème liquide jusqu''à frémissement.','Versez sur le chocolat blanc haché, laissez fondre puis mélangez.','Incorporez le beurre et la vanille, mélangez jusqu''à obtenir une sauce lisse.']::text[], 'Fiche recette envoyée par Renée-Lise le 15/11 — repère interne (composition/préparation), pas de prix de vente associé.', 'actif'),
('Ganache au Chocolat', 'sauce', 6, 1, 10, 5, null, '[{"nom": "Chocolat noir, haché", "quantite": 250, "unite": "g"}, {"nom": "Crème liquide", "quantite": 250, "unite": "ml"}]'::jsonb, ARRAY['Faites chauffer la crème liquide jusqu''à frémissement.','Versez-la sur le chocolat noir haché, laissez fondre 1 à 2 minutes.','Mélangez jusqu''à obtenir une ganache lisse et brillante.']::text[], 'Fiche recette envoyée par Renée-Lise le 15/11 — repère interne (composition/préparation), pas de prix de vente associé.', 'actif'),
('Sauce Caramel au Beurre', 'sauce', 4, 1, 10, 10, null, '[{"nom": "Sucre", "quantite": 200, "unite": "g", "notes": "1 tasse"}, {"nom": "Eau", "quantite": 60, "unite": "ml", "notes": "1/4 tasse"}, {"nom": "Crème liquide", "quantite": 120, "unite": "ml", "notes": "1/2 tasse"}, {"nom": "Beurre", "quantite": 30, "unite": "g", "notes": "2 c. à soupe"}, {"nom": "Extrait de vanille", "quantite": 1, "unite": "c. à café"}]'::jsonb, ARRAY['Faites chauffer le sucre et l''eau jusqu''à obtenir un caramel ambré.','Hors du feu, incorporez la crème liquide chaude petit à petit en fouettant.','Ajoutez le beurre et la vanille, mélangez jusqu''à obtenir une sauce lisse.']::text[], 'Fiche recette envoyée par Renée-Lise le 15/11 — repère interne (composition/préparation), pas de prix de vente associé.', 'actif'),
('Sauce Caramel au Sel', 'sauce', 4, 1, 10, 10, null, '[{"nom": "Sucre", "quantite": 200, "unite": "g"}, {"nom": "Eau", "quantite": 60, "unite": "ml"}, {"nom": "Crème liquide", "quantite": 120, "unite": "ml"}, {"nom": "Beurre", "quantite": 45, "unite": "g", "notes": "3 c. à soupe"}, {"nom": "Fleur de sel", "quantite": 1, "unite": "c. à café"}]'::jsonb, ARRAY['Faites chauffer le sucre et l''eau jusqu''à obtenir un caramel ambré.','Hors du feu, incorporez la crème liquide chaude petit à petit en fouettant.','Ajoutez le beurre et la fleur de sel, mélangez jusqu''à obtenir une sauce lisse.']::text[], 'Fiche recette envoyée par Renée-Lise le 15/11 — repère interne (composition/préparation), pas de prix de vente associé.', 'actif'),
('Crème pâtissière classique', 'dessert', 6, 2, 15, 10, 120, '[{"nom": "Lait", "quantite": 500, "unite": "ml"}, {"nom": "Maïzena", "quantite": 40, "unite": "g"}, {"nom": "Sucre", "quantite": 100, "unite": "g"}, {"nom": "Jaunes d''œufs", "quantite": 4, "unite": "piece"}, {"nom": "Extrait de vanille", "quantite": 1, "unite": "c. à café"}]'::jsonb, ARRAY['Faites chauffer le lait avec la vanille jusqu''à frémissement.','Fouettez les jaunes d''œufs avec le sucre et la Maïzena jusqu''à blanchiment.','Versez le lait chaud sur ce mélange en fouettant, puis reversez le tout dans la casserole.','Faites épaissir à feu doux sans cesser de remuer jusqu''à obtenir une crème nappante.','Filmez au contact et laissez refroidir au réfrigérateur au moins 2 heures.']::text[], 'Fiche recette envoyée par Renée-Lise le 15/11 — repère interne (composition/préparation), pas de prix de vente associé.', 'actif'),
('Crème pâtissière au chocolat', 'dessert', 6, 2, 15, 10, 120, '[{"nom": "Lait", "quantite": 500, "unite": "ml"}, {"nom": "Maïzena", "quantite": 40, "unite": "g"}, {"nom": "Sucre", "quantite": 100, "unite": "g"}, {"nom": "Jaunes d''œufs", "quantite": 4, "unite": "piece"}, {"nom": "Chocolat noir", "quantite": 100, "unite": "g"}]'::jsonb, ARRAY['Faites chauffer le lait jusqu''à frémissement.','Fouettez les jaunes d''œufs avec le sucre et la Maïzena jusqu''à blanchiment.','Versez le lait chaud sur ce mélange en fouettant, puis reversez le tout dans la casserole.','Faites épaissir à feu doux sans cesser de remuer, puis hors du feu ajoutez le chocolat noir haché et mélangez jusqu''à ce qu''il soit fondu.','Filmez au contact et laissez refroidir au réfrigérateur au moins 2 heures.']::text[], 'Fiche recette envoyée par Renée-Lise le 15/11 — repère interne (composition/préparation), pas de prix de vente associé.', 'actif'),
('Crème pâtissière sans œufs', 'dessert', 6, 1, 15, 10, 120, '[{"nom": "Lait", "quantite": 500, "unite": "ml"}, {"nom": "Maïzena", "quantite": 40, "unite": "g"}, {"nom": "Sucre", "quantite": 80, "unite": "g"}, {"nom": "Sucre vanillé", "quantite": 1, "unite": "sachet"}, {"nom": "Beurre", "quantite": 30, "unite": "g"}]'::jsonb, ARRAY['Délayez la Maïzena, le sucre et le sucre vanillé avec un peu de lait froid.','Faites chauffer le reste du lait, puis versez-y le mélange en fouettant.','Faites épaissir à feu doux sans cesser de remuer jusqu''à obtenir une crème nappante.','Hors du feu, incorporez le beurre en morceaux et mélangez jusqu''à ce qu''il soit fondu.','Filmez au contact et laissez refroidir au réfrigérateur au moins 2 heures.']::text[], 'Fiche recette envoyée par Renée-Lise le 15/11 — repère interne (composition/préparation), pas de prix de vente associé.', 'actif'),
('Génoise pour layer cake', 'cake', 14, 2, 20, 58, null, '[{"nom": "Œufs, température ambiante", "quantite": 8, "unite": "piece", "notes": "pour un moule de 20 cm x 7,5 cm"}, {"nom": "Sucre", "quantite": 240, "unite": "g"}, {"nom": "Farine", "quantite": 240, "unite": "g"}, {"nom": "Levure chimique", "quantite": 10, "unite": "g", "notes": "1 sachet + 1/4"}, {"nom": "Lait entier", "quantite": 160, "unite": "ml"}, {"nom": "Huile neutre", "quantite": 130, "unite": "ml"}, {"nom": "Extrait de vanille", "quantite": 1, "unite": "c. à café"}]'::jsonb, ARRAY['Fouettez les œufs et le sucre jusqu''à ce que le mélange triple de volume et blanchisse (mousse épaisse).','Tamisez la farine et la levure puis incorporez-les délicatement à la maryse, en 2 à 3 fois.','Ajoutez le lait, l''huile et la vanille, mélangez délicatement jusqu''à obtenir une pâte lisse et homogène.','Versez dans le moule chemisé, aux 2/3 maximum.','Enfournez à 150-160°C (chaleur tournante) : environ 55 à 60 minutes pour un moule de 20 cm (voir le tableau en notes pour les autres tailles).']::text[], 'Fiche recette envoyée par Renée-Lise le 15/11 — repère interne (composition/préparation), pas de prix de vente associé. Quantités pour une génoise haute à 3 couches, selon la taille du moule (diamètre x 7,5 cm de hauteur) : 15 cm (6 à 8 parts) → 6 œufs, 180 g sucre, 180 g farine, 8 g levure, 120 ml lait, 100 ml huile, 1 c. à café vanille, cuisson 45-50 min. 18 cm (8 à 12 parts) → 7 œufs, 210 g sucre, 210 g farine, 8 g levure, 140 ml lait, 120 ml huile, 1 c. à café vanille, cuisson 50-55 min. 20 cm (12 à 16 parts) → 8 œufs, 240 g sucre, 240 g farine, 10 g levure, 160 ml lait, 130 ml huile, 1 c. à café vanille, cuisson 55-60 min. 22 cm (16 à 20 parts) → 9 œufs, 270 g sucre, 270 g farine, 10 g levure, 180 ml lait, 150 ml huile, 1 à 2 c. à café vanille, cuisson 60-65 min. 25 cm (20 à 26 parts) → 10 œufs, 300 g sucre, 300 g farine, 12 g levure, 200 ml lait, 170 ml huile, 1 à 2 c. à café vanille, cuisson 65-70 min. Astuces : ingrédients à température ambiante ; ne pas ouvrir le four pendant les 30 premières minutes ; laisser refroidir complètement avant de découper et garnir ; imbiber légèrement avec un sirop (eau, sucre, vanille) pour plus de moelleux ; filmer et placer au frais 2 à 4h (idéalement une nuit) avant de monter le layer cake.', 'actif')
) as v(nom, categorie, nb_parts, difficulte, temps_prepa, temps_cuisson, temps_repos, ingredients, etapes, notes, statut)
where not exists (
  select 1 from public.food_recettes fr where fr.nom = v.nom and fr.notes = v.notes
);
